INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-season-7900581', 'course-bili-season-7900581', '100001', '0', 'BILI-OPS-033', 'course-category-operations', 'instructor-bili-3546877742025259', '2026拼多多微付费带自然流【UP主的实战玩法】', '7 讲完整课程 · 3 小时 48 分钟', '为什么最近很多人店铺莫名其妙断流，系统没有任何提醒链接直接关小黑屋，刚上架的链接直接死掉，开推广没有任何花费没有曝光，刚上架的链接系统不给发布，审核莫名其妙说有问题，一阶段正常能过，二阶段直接断流，为什么会遇到这些问题和', '课程简介：为什么最近很多人店铺莫名其妙断流，系统没有任何提醒链接直接关小黑屋，刚上架的链接直接死掉，开推广没有任何花费没有曝光，刚上架的链接系统不给发布，审核莫名其妙说有问题，一阶段正常能过，二阶段直接断流，为什么会遇到这些问题和产生这些问题，那么我们就要认真的去阅读一下，拼多多9月9号以及9月30号更新的两条新规。第一就是9月9号更新的加强AB货治理的通知，第二就是9月30号更新的所有类目加强抽检描述以及产品质量的通知，大家要特别注意的是9月30号的商品质量抽检其实在今年上半年618之前已经更新过一次，这个老粉丝应该都知道，所以这一次严格意义上来说，不能算更新算是加强商品抽检。但是这一次有一点算是好事，这一次系统明确了整个类目的抽检细节，以后不用靠猜了，所以大家可以根据自己的类目去看规则。好那么这两条规则更新意味着什么呢？意味着平台现在是死磕商品质量问题，所以就导致了很多人遇到了各种各样的问题。总结一句话：现在的拼多多并不是变难做了，而是这个平台越来越正规，而且很明显的能够感觉到这个平台的门槛提高了，如果现在大家做链接还是跟以前一样随便搞几张图片就上架到处盗图弄一弄改一改就卖货，基本就是抽检就是死。课程结构：共 1 章 7 讲，累计时长 3 小时 48 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["掌握内容选题、脚本、拍摄与剪辑的完整生产链路","理解平台推荐机制与账号冷启动方法","搭建可复用的内容日历、数据复盘与投放模型","具备从零起号到商业变现的实战能力"]', '["零基础想做新媒体运营的职场人","需要提升账号数据的自媒体创作者","实体商家与品牌市场人员"]', '["有常用社交平台的真实使用经验","无需拍摄设备，手机即可完成练习"]', 'intermediate', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/d27baa17cd9546a1a63ff2b0403d4d4afa046e8e.jpg', '["运营营销","新媒体","增长实战","UP主的实战玩法"]', 13714, 7, 1711, '4.5', 293, 'BV16kpi6fEJx', NULL, NULL, NULL, 1, 0, 'standard', NULL, '拼多多运营锕麦', 0, 'tenant', 'published', '2026-10-13T13:45:36.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
